      setCompetitionFormat(activeCompetition.format === 'ROUND_ROBIN' ? 'ROUND_ROBIN_SINGLE' : activeCompetition.format);setMinTeams(activeCompetition.min_teams??2);setMaxTeams(activeCompetition.max_teams??64);
